}
}
stream = php_stream_open_wrapper(file, "rb", REPORT_ERRORS|IGNORE_PATH|IGNORE_URL_WIN, NULL);
if (stream == NULL)	{
RETURN_FALSE;
}
#ifndef USE_GD_IOCTX
ioctx_func_p = NULL;
#endif
if (image_type == PHP_GDIMG_TYPE_WEBP) {
size_t buff_size;
